            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s006_e02", prompt = "Quel rôle joue un fichier de verrouillage pour une application ?", options = listOf("Conserver une résolution précise des dépendances.", "Remplacer le code source.", "Garantir à lui seul l’absence de vulnérabilités.", "Empêcher toute modification de configuration."), correctOptionIndex = 0, explanation = "Il enregistre les versions choisies, et souvent leurs références ou empreintes, pour retrouver une résolution déterminée.", hint = "Distinguer une plage autorisée et un choix concret."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s006_e03", prompt = "Pourquoi distribuer un wheel Python plutôt que supposer que le module sera trouvé depuis n’importe quel dossier ?", options = listOf("Un wheel élimine le besoin d’un interpréteur dans tous les cas.", "Un wheel fonctionne forcément sur toutes les architectures.", "Le dossier courant n’a jamais d’effet sur les imports.", "Le wheel fournit un paquet installable et ses métadonnées."), correctOptionIndex = 3, explanation = "L’installation place le paquet et ses métadonnées dans les emplacements de l’environnement. Les contraintes de plateforme et de runtime peuvent subsister.", hint = "L’artefact doit avoir un contrat d’installation."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s006_e04", prompt = "Sous SemVer, une bibliothèque stable 2.4.1 supprime une fonction publique sans remplacement compatible. Quel changement de version correspond à cette rupture ?", options = listOf("2.5.0", "2.4.1", "3.0.0", "2.4.2"), correctOptionIndex = 2, explanation = "Pour une bibliothèque stable respectant SemVer, les changements incompatibles demandent d’incrémenter la version majeure.", hint = "L’énoncé précise une API stable après 1.0."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s006_e05", prompt = "Quelle distinction entre image et conteneur est correcte ?", options = listOf("Une image ne peut créer qu’un seul conteneur.", "L’image est l’artefact ; le conteneur en est une instance d’exécution.", "L’image est toujours une machine virtuelle complète.", "Un conteneur ne contient aucun processus."), correctOptionIndex = 1, explanation = "Plusieurs conteneurs peuvent être instanciés à partir du même artefact image.", hint = "Comparer modèle emballé et instance active."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s006_e06", prompt = "Même binaire en préproduction et en production, mais bases de données différentes : quelle approche convient ?", options = listOf("Fournir l’URL de base par configuration d’exécution.", "Compiler obligatoirement deux codes sources divergents.", "Inscrire les mots de passe dans le dépôt public.", "Supprimer toutes les options de configuration."), correctOptionIndex = 0, explanation = "La configuration permet de changer l’environnement cible en conservant l’artefact testé ; les secrets se fournissent séparément.", hint = "Faire varier les paramètres plutôt que le comportement codé en dur.")
        ),
        objective = "Relier dépendances, paquet, environnement et publication.",
        learningNotes = "## Décrire ce qu’il faut livrer\n\nUn artefact doit préciser ses besoins : interpréteur, bibliothèques, système et configuration. Un environnement virtuel isole les paquets Python du projet. Une contrainte de version indique les choix acceptables. Un fichier de verrouillage consigne une résolution concrète pour reconstruire l’application.\n\nUn **wheel** est un paquet Python installable avec ses métadonnées. Le dossier source seul ne garantit pas que l’installation fonctionnera depuis un autre emplacement.\n\n## Séparer paquet, exécution et configuration\n\nAprès la version 1.0, SemVer réserve le changement majeur aux ruptures de compatibilité. Vérifier que le projet suit bien cette convention. Une image de conteneur sert de modèle à des conteneurs, qui partagent le noyau de leur environnement hôte. La configuration d’exécution et les secrets restent séparés de l’artefact.\n\n## À retenir\n\nUne livraison fiable associe un artefact identifié, des contrôles adaptés et un moyen de revenir à une version connue.",
        sourceUrls = listOf("https://missing.csail.mit.edu/2026/shipping-code/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 6,
        sourceTitle = "Packaging and Shipping Code",
        sessionKind = "lesson"
    )

    private fun lesson007() = Lesson(
        id = "mit_missing_semester_2026_s007",
        title = "Piloter un agent de programmation",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s007_e01", prompt = "Quel énoncé décrit un objectif vérifiable pour un agent modifiant une commande ?", options = listOf("Ajouter --limit N ; avec N=2 sur ce fichier de trois lignes, la sortie attendue contient exactement les deux premières.", "Améliore tout le projet.", "Rends le code parfait.", "Choisis au hasard de nouvelles fonctionnalités."), correctOptionIndex = 0, explanation = "Le premier énoncé fournit une entrée, une option et un résultat observable qui servent à contrôler l’implémentation.", hint = "Un contrat concret doit permettre de reconnaître la réussite."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s007_e02", prompt = "L’agent annonce une correction de type, mais le vérificateur échoue encore. Quelle suite exploite réellement une boucle de retour ?", options = listOf("Accepter l’annonce comme preuve suffisante.", "Masquer la sortie d’erreur.", "Supprimer les annotations pour ne plus voir le problème.", "Lui fournir le diagnostic exact et la commande reproductible, puis examiner sa correction."), correctOptionIndex = 3, explanation = "Le retour du vérificateur renseigne l’agent sur l’échec restant et permet une nouvelle proposition contrôlable.", hint = "Une action observée est plus informative qu’une annonce."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s007_e03", prompt = "Deux agents modifient des fonctionnalités indépendantes. Quel outil Git permet des répertoires de travail séparés avec des branches distinctes ?", options = listOf("git blame uniquement.", "git status uniquement.", "git worktree", "git diff uniquement."), correctOptionIndex = 2, explanation = "Un worktree fournit un autre répertoire de travail lié au même dépôt, évitant l’édition concurrente des mêmes fichiers de travail.", hint = "Séparer les espaces de modification."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s007_e04", prompt = "Pourquoi transmettre un résumé des décisions et les fichiers utiles plutôt qu’un très grand journal sans sélection ?", options = listOf("Les fichiers source sont forcément moins fiables qu’un résumé.", "Le contexte est limité et les informations inutiles peuvent masquer les éléments nécessaires.", "Le modèle n’a jamais besoin de lire du code.", "Un résumé garantit toujours une solution exacte."), correctOptionIndex = 1, explanation = "Le résumé conserve les contraintes et décisions ; les références permettent de relire les sources quand le détail est nécessaire.", hint = "Conserver l’information pertinente et sa traçabilité."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s007_e05", prompt = "Un agent s’exécute dans un terminal local. Cela garantit-il que les données restent sur cette machine ?", options = listOf("Non ; il faut vérifier où s’effectue l’inférence et quelles données l’outil transmet.", "Oui, le terminal garantit une inférence locale.", "Oui, si le dépôt n’a pas de distant Git.", "Oui, si le programme est écrit en Python."), correctOptionIndex = 0, explanation = "L’interface locale et le modèle peuvent fonctionner dans des environnements différents ; la configuration détermine la circulation des données.", hint = "Distinguer le lieu de l’interface et celui du calcul du modèle.")
        ),
        objective = "Définir un objectif vérifiable et une boucle de retour.",
        learningNotes = "## Formuler un résultat vérifiable\n\nUn agent de programmation associe un modèle de langage à des outils pour lire des fichiers, proposer des changements et lancer des vérifications. Le programme qui l’entoure lui transmet les résultats afin qu’il puisse ajuster ses actions. Une demande utile précise le résultat observable, les contraintes et la façon de juger la réussite.\n\nPar exemple, pour corriger un défaut de type, fournir le diagnostic et la commande de vérification donne une boucle de retour concrète :\n\n```text\nObjectif : corriger l’erreur de type signalée dans fichier.py.\nVérification : exécuter la commande exacte et confirmer que ce diagnostic disparaît.\n```\n\n## Garder le contexte utile\n\nLa fenêtre de contexte est limitée : conserver les décisions et références utiles facilite la suite du travail. Des tâches indépendantes peuvent utiliser des espaces de travail séparés créés par `git worktree` pour limiter les collisions de fichiers.\n\n## À retenir\n\nUn lancement local ne garantit pas que l’inférence du modèle est locale. Les réglages d’accès et de confidentialité dépendent de l’outil utilisé.",
        sourceUrls = listOf("https://missing.csail.mit.edu/2026/agentic-coding/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 7,
        sourceTitle = "Agentic Coding",
        sessionKind = "lesson"
    )

    private fun lesson008() = Lesson(
        id = "mit_missing_semester_2026_s008",
        title = "Écrire pour les futurs lecteurs",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s008_e01", prompt = "Quel commentaire apporte une raison utile à une constante de tentatives ?", options = listOf("Définir le nombre trois.", "La variable contient une valeur.", "Faire une boucle.", "Trois tentatives limitent la durée totale à notre budget de deux secondes."), correctOptionIndex = 3, explanation = "La raison relie la constante à une contrainte de durée, ce qui aide le futur lecteur à décider s’il peut la modifier.", hint = "Expliquer une décision difficile à déduire du code."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s008_e02", prompt = "Quel élément manque le plus à « l’import ne marche pas » pour constituer un signalement exploitable ?", options = listOf("Le nombre de collègues dans l’équipe.", "Une capture décorative sans diagnostic.", "Un exemple minimal avec versions, commande exacte, résultat attendu et erreur observée.", "Une préférence de couleur pour l’éditeur."), correctOptionIndex = 2, explanation = "Le mainteneur a besoin de reproduire les conditions et la divergence de comportement, pas seulement d’un symptôme général.", hint = "Transformer une plainte en expérience reproductible."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s008_e03", prompt = "Une correction de bug et un changement de palette sans rapport sont prêts. Quelle organisation facilite la revue ?", options = listOf("Effacer toutes les explications historiques.", "Deux changements cohérents, chacun avec sa motivation.", "Un seul changement sans description.", "Ajouter encore plusieurs sujets pour rentabiliser la revue."), correctOptionIndex = 1, explanation = "Séparer les objectifs permet de comprendre, accepter et éventuellement revenir sur chaque changement indépendamment.", hint = "Regrouper par intention, pas par moment d’édition."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s008_e04", prompt = "Quel retour de revue est le plus directement exploitable ?", options = listOf("Quand la liste est vide, cette division échoue ; ajouter un traitement avant le calcul.", "Ce code est mauvais.", "Tout est confus.", "Je n’aime pas ta façon de coder."), correctOptionIndex = 0, explanation = "Le retour nomme une condition déclenchante, une conséquence et une direction de correction, sans attaquer la personne.", hint = "Préciser scénario et effet observables."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s008_e05", prompt = "Un message de commit décrit seulement « remplacer le cache ». Quelle information aide le mieux à conserver la décision ?", options = listOf("Le numéro de chaise du développeur.", "Une copie intégrale de tous les fichiers modifiés.", "Uniquement le nombre de caractères du diff.", "Le défaut constaté, la raison du choix du nouveau cache et ses implications."), correctOptionIndex = 3, explanation = "Les lecteurs futurs peuvent voir ce qui a changé dans le diff, mais le motif et les compromis risquent de se perdre.", hint = "Le message doit apporter du contexte absent de la différence.")
        ),
        objective = "Rendre une modification compréhensible et une contribution reproductible.",
        learningNotes = "## Écrire ce que le code ne dit pas\n\nUn commentaire utile expose une raison, une contrainte ou un invariant qui n’est pas évident à la lecture du code. Un `README` explique le but, montre un usage et prépare l’installation. Un message de commit garde la motivation du changement et ses conséquences.\n\n## Rendre une panne reproductible\n\nUn signalement exploitable indique l’environnement, la version, une entrée minimale, les étapes, le résultat attendu et le résultat observé. En revue, relier un commentaire à un scénario et à son effet aide l’auteur à agir. Distinguer un défaut bloquant d’une suggestion clarifie la priorité.\n\n## À retenir\n\nRegrouper une contribution par intention facilite sa revue. L’auteur doit comprendre et pouvoir expliquer le changement proposé, y compris lorsqu’une assistance IA a été utilisée.",
        sourceUrls = listOf("https://missing.csail.mit.edu/2026/beyond-code/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 8,
        sourceTitle = "Beyond the Code",
        sessionKind = "lesson"
    )

    private fun lesson009() = Lesson(
        id = "mit_missing_semester_2026_s009",
        title = "Automatiser des contrôles de qualité",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s009_e01", prompt = "Quel outil vérifie principalement l’uniformité de l’indentation et de l’espacement ?", options = listOf("Un gestionnaire de paquets.", "Un débogueur à points d’arrêt.", "Un formateur.", "Un profileur mémoire."), correctOptionIndex = 2, explanation = "Le formateur normalise la présentation du code ; les autres outils visent des problèmes différents.", hint = "La question porte sur la forme de la source."),
            Exercise.CodeChallenge(id = "mit_missing_semester_2026_s009_e02", prompt = "Quel défaut rend ce test insuffisant pour vérifier addition ?", codeSnippet = "def test_addition():\n    addition(2, 3)", options = listOf("Il contient un nom de fonction.", "Il n’affirme rien sur le résultat retourné.", "Il utilise deux arguments entiers.", "Il appelle la fonction une fois."), correctOptionIndex = 1, explanation = "Le code peut être exécuté et couvert même si addition renvoie une valeur erronée. Une assertion sur le résultat attendu est nécessaire.", hint = "Une exécution sans panne ne prouve pas le résultat."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s009_e03", prompt = "Une fonction de tri a oublié une valeur tout en conservant l’ordre. Quelle propriété supplémentaire détecte ce défaut ?", options = listOf("La sortie contient le même multiensemble d’éléments que l’entrée.", "La sortie est seulement croissante.", "La fonction a un nom court.", "Le fichier possède une extension connue."), correctOptionIndex = 0, explanation = "L’ordre seul n’assure pas la conservation des valeurs et de leurs multiplicités. Comparer les multisets détecte les pertes et duplications.", hint = "Un tri doit réordonner sans perdre ni créer de valeurs."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s009_e04", prompt = "Que prouve une couverture de lignes de 100 % à elle seule ?", options = listOf("Le programme n’a aucun défaut.", "Chaque résultat a été vérifié.", "Toutes les entrées possibles ont été essayées.", "Toutes les lignes mesurées ont été exécutées par les tests."), correctOptionIndex = 3, explanation = "La couverture observe le passage sur les lignes, pas la qualité des assertions ni l’exhaustivité des cas.", hint = "Distinguer exécution et validation du comportement."),
            Exercise.CodeChallenge(id = "mit_missing_semester_2026_s009_e05", prompt = "Avec Python re.fullmatch, quelle chaîne correspond à ce motif sans pour autant être une date valide ?", codeSnippet = "r\"\\d{4}-\\d{2}-\\d{2}\"", options = listOf("`2026/01/09`", "texte", "2026-01-99", "26-01-09"), correctOptionIndex = 2, explanation = "Le motif impose quatre, deux et deux chiffres séparés par des tirets. Il n’examine pas les jours autorisés par le calendrier.", hint = "Un motif de forme ne connaît pas les règles du calendrier."),
            Exercise.MultipleChoice(id = "mit_missing_semester_2026_s009_e06", prompt = "Quel avantage apporte une CI testant Python 3.11 et 3.12 sous Linux et Windows ?", options = listOf("Elle prouve que les dépendances ne changeront jamais.", "Elle explore les interactions entre versions du runtime et systèmes sur les quatre combinaisons.", "Elle garantit tous les matériels possibles.", "Elle remplace toutes les assertions."), correctOptionIndex = 1, explanation = "Une matrice de deux versions et deux systèmes produit quatre environnements vérifiés, ce qui dépasse une seule machine sans couvrir tous les environnements.", hint = "Compter les combinaisons et garder la portée du contrôle.")
        ),
        objective = "Distinguer formatage, analyse statique, tests et intégration continue.",
        learningNotes = "## Distinguer les contrôles\n\nUn formateur harmonise la présentation du code. Un linter cherche des motifs suspects sans exécuter le programme. Les tests exercent des comportements et doivent vérifier des résultats pertinents : exécuter une ligne sans erreur ne prouve pas que sa réponse est juste.\n\nUn test de régression garde un cas de panne corrigé pour éviter son retour. Un test de propriété vérifie une règle sur plusieurs entrées. Les hooks locaux donnent un retour rapide. L’intégration continue (CI) exécute les contrôles dans un environnement distinct, par exemple avec plusieurs versions du runtime. Un lanceur de commandes fournit des points d’entrée communs à l’équipe.\n\n## Connaître la portée d’un contrôle\n\nUne expression régulière décrit une forme. Un motif peut reconnaître `2026-02-31` comme trois groupes de chiffres séparés par des tirets sans vérifier que cette date existe dans le calendrier.\n\n## À retenir\n\nDes contrôles complémentaires renforcent la confiance, mais aucun indicateur isolé — même 100 % de lignes couvertes — ne prouve à lui seul l’absence de défauts.",
        sourceUrls = listOf("https://missing.csail.mit.edu/2026/code-quality/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 9,
        sourceTitle = "Code Quality",
        sessionKind = "lesson"
    )
}
